public static Object deserialize(String base64String) throws Exception {
        // Decode de base64-string naar een byte-array
        byte[] decodedBytes = Base64.getDecoder().decode(base64String);

        // Maak een ByteArrayInputStream om de byte-array te lezen
        ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(decodedBytes);

        // Maak een ObjectInputStream om de serialiseerde objecten te lezen
        ObjectInputStream objectInputStream = new ObjectInputStream(byteArrayInputStream);

        // Lees het serialiseerde object uit de InputStream
        Object deserializedObject = objectInputStream.readObject();

        // Sluit de streams
        objectInputStream.close();
        byteArrayInputStream.close();

        return deserializedObject;
    }
}
