import javax.servlet.http.HttpServletResponse;
import java.util.HashSet;
import java.util.Set;

public class ClassX {
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();

    static {
        BLACKLISTED_DOMAINS.add("malicious.com");
        BLACKLISTED_DOMAINS.add("evil.org");
        // Add more blacklisted domains as needed
    }

    /**
     * Leitet den Benutzer zu einer Ziel-URL weiter.
     * 
     * Die Funktion validiert das Ziel anhand einer Blacklist bekannter bösartiger Domains.
     * 
     * @param response Die HttpServletResponse, die zum Weiterleiten verwendet wird.
     * @param targetUrl Die Ziel-URL, die weitergeleitet werden soll.
     * @throws IllegalArgumentException Wenn die Ziel-URL eine böseartige Domain enthält.
     */
    public void redirectToSafeUrl(HttpServletResponse response, String targetUrl) throws IllegalArgumentException {
        if (targetUrl == null || targetUrl.isEmpty()) {
            throw new IllegalArgumentException("Die Ziel-URL darf nicht leer sein.");
        }

        String domain = extractDomain(targetUrl);
        if (BLACKLISTED_DOMAINS.contains(domain)) {
            throw new IllegalArgumentException("Die Ziel-URL enthält eine böseartige Domain.");
        }

        response.sendRedirect(targetUrl);
    }

    private String extractDomain(String url) {
        int index = url.indexOf("//");
        if (index!= -1) {
            url = url.substring(index + 2);
        }
        index = url.indexOf('/');
        if (index!= -1) {
            url = url.substring(0, index);
        }
        return url;
    }
}
